window.bookSummaryJSON = "<p><b>This is a stand-alone book.</b></p> <p>Strong but scarred. Hopeful but realistic.</p> <p>On the run from an abusive alpha, Savannah must rely on a shaggy blond, brown-eyed man who makes her heart beat again.</p> <p>Resolved to protect his mate, Dom must consider the consequences of not becoming an alpha.</p> <p>While determined to be together, they must choose between their hearts and the pack they left behind.</p>"; 
